BANK = {'SAT': [{'id': 'sat01', 'topic': 'Algebra', 'difficulty': 'foundation', 'text': 'Solve 4x − 7 = 21.', 'options': ['x = 5', 'x = 7', 'x = 9', 'x = 14'], 'correct': 1, 'explanation': 'Add 7, then divide 28 by 4.'}, {'id': 'sat02', 'topic': 'Algebra', 'difficulty': 'foundation', 'text': 'If y = 3x + 2, what is y when x = 4?', 'options': ['10', '12', '14', '16'], 'correct': 2, 'explanation': '3 × 4 + 2 = 14.'}, {'id': 'sat03', 'topic': 'Algebra', 'difficulty': 'intermediate', 'text': 'The equations y = 2x + 3 and y = −x + 12 intersect at what x-value?', 'options': ['2', '3', '4', '5'], 'correct': 1, 'explanation': 'Set the expressions equal: 2x + 3 = −x + 12, so 3x = 9.'}, {'id': 'sat04', 'topic': 'Algebra', 'difficulty': 'intermediate', 'text': 'A linear function decreases by 5 when x increases by 2. Its slope is:', 'options': ['−5/2', '−2/5', '2/5', '5/2'], 'correct': 0, 'explanation': 'Slope is change in y divided by change in x.'}, {'id': 'sat05', 'topic': 'Data analysis', 'difficulty': 'foundation', 'text': 'A jacket costs $80 and is discounted by 25%. What is the new price?', 'options': ['$20', '$55', '$60', '$65'], 'correct': 2, 'explanation': '25% of $80 is $20; subtract it from $80.'}, {'id': 'sat06', 'topic': 'Data analysis', 'difficulty': 'foundation', 'text': 'The numbers 4, 6, 9, 9, 12 have median:', 'options': ['6', '8', '9', '10'], 'correct': 2, 'explanation': 'The middle of five ordered numbers is the third: 9.'}, {'id': 'sat07', 'topic': 'Data analysis', 'difficulty': 'intermediate', 'text': 'A sample of 40 students includes 18 who bike to school. What percentage bike?', 'options': ['35%', '40%', '45%', '55%'], 'correct': 2, 'explanation': '18 ÷ 40 × 100 = 45%.'}, {'id': 'sat08', 'topic': 'Data analysis', 'difficulty': 'intermediate', 'text': 'A population of 300 grows by 10% and then decreases by 10%. Final population?', 'options': ['297', '300', '303', '330'], 'correct': 0, 'explanation': '300 × 1.10 × 0.90 = 297.'}, {'id': 'sat09', 'topic': 'Reading & Writing', 'difficulty': 'foundation', 'text': 'Choose the grammatically correct sentence.', 'options': ['The team are preparing its poster.', 'The team is preparing its poster.', 'The team is prepare its poster.', 'The team were prepares its poster.'], 'correct': 1, 'explanation': 'Team is treated as a singular collective noun here.'}, {'id': 'sat10', 'topic': 'Reading & Writing', 'difficulty': 'foundation', 'text': 'Which transition best signals a contrast?', 'options': ['Furthermore', 'For example', 'However', 'Therefore'], 'correct': 2, 'explanation': 'However introduces a contrasting idea.'}, {'id': 'sat11', 'topic': 'Reading & Writing', 'difficulty': 'intermediate', 'text': 'Which revision is most concise? “Due to the fact that it was raining, the match was delayed.”', 'options': ['Because it rained, the match was delayed.', 'The match, due to rain, was in a delayed condition.', 'Rain was a fact and the match delayed.', 'The match was delayed due to the fact that it rained.'], 'correct': 0, 'explanation': 'Because it rained expresses the same idea more directly.'}, {'id': 'sat12', 'topic': 'Reading & Writing', 'difficulty': 'intermediate', 'text': 'A report finds a correlation between exercise and sleep quality. Which conclusion is best supported?', 'options': ['Exercise always causes better sleep.', 'The measures are associated, but causation is not established.', 'Sleep quality cannot affect exercise.', 'The report proves no other factors matter.'], 'correct': 1, 'explanation': 'Correlation alone does not prove a cause-and-effect relationship.'}], 'ACT': [{'id': 'act01', 'topic': 'English', 'difficulty': 'foundation', 'text': 'Choose the correct sentence.', 'options': ['Its a useful chart.', 'It’s a useful chart.', 'Its’ a useful chart.', 'It a useful chart.'], 'correct': 1, 'explanation': 'It’s means “it is”; its is possessive.'}, {'id': 'act02', 'topic': 'English', 'difficulty': 'foundation', 'text': 'Which sentence uses a comma correctly?', 'options': ['After school, Mira reviewed her notes.', 'After school Mira, reviewed her notes.', 'After, school Mira reviewed her notes.', 'After school Mira reviewed, her notes.'], 'correct': 0, 'explanation': 'A comma separates the introductory phrase.'}, {'id': 'act03', 'topic': 'English', 'difficulty': 'intermediate', 'text': 'Choose the best revision: “The robot was small in size and was also very fast in speed.”', 'options': ['The robot was small and fast.', 'The robot was small in size, and it had fast speed.', 'The robot had small size and fast speed.', 'The robot was of a small size and fast.'], 'correct': 0, 'explanation': 'Remove unnecessary repeated ideas.'}, {'id': 'act04', 'topic': 'English', 'difficulty': 'intermediate', 'text': 'Choose the sentence with correct subject–verb agreement.', 'options': ['Neither the coach nor the players was ready.', 'Neither the coach nor the players were ready.', 'Neither the coach or the players was ready.', 'Neither the coach nor the players is ready.'], 'correct': 1, 'explanation': 'With neither/nor, the plural nearer subject “players” takes were.'}, {'id': 'act05', 'topic': 'Math', 'difficulty': 'foundation', 'text': 'A triangle has angles of 45° and 65°. What is the third angle?', 'options': ['60°', '70°', '75°', '80°'], 'correct': 1, 'explanation': 'Angles in a triangle sum to 180°: 180 − 45 − 65 = 70.'}, {'id': 'act06', 'topic': 'Math', 'difficulty': 'foundation', 'text': 'What is 15% of 200?', 'options': ['15', '25', '30', '35'], 'correct': 2, 'explanation': '0.15 × 200 = 30.'}, {'id': 'act07', 'topic': 'Math', 'difficulty': 'intermediate', 'text': 'If 2(x − 3) = 5x + 9, x equals:', 'options': ['−5', '−3', '3', '5'], 'correct': 0, 'explanation': '2x − 6 = 5x + 9 implies −15 = 3x.'}, {'id': 'act08', 'topic': 'Math', 'difficulty': 'intermediate', 'text': 'A rectangle has perimeter 30 and width 6. Its length is:', 'options': ['7', '8', '9', '12'], 'correct': 2, 'explanation': '2(l + 6) = 30, so l = 9.'}, {'id': 'act09', 'topic': 'Reading', 'difficulty': 'foundation', 'text': 'A city installed more bike racks and reported greater bicycle use. Which fact would help evaluate the cause?', 'options': ['The racks’ color', 'Whether cycling had increased before installation', 'Number of streetlights in another city', 'The mayor’s favorite sport'], 'correct': 1, 'explanation': 'A prior trend may explain some of the observed change.'}, {'id': 'act10', 'topic': 'Reading', 'difficulty': 'intermediate', 'text': 'An author presents two opposing opinions before proposing a compromise. The structure primarily:', 'options': ['Lists events in time order', 'Contrasts perspectives then offers a resolution', 'Explains a mathematical procedure', 'Defines technical vocabulary'], 'correct': 1, 'explanation': 'Two opposing views are compared before a solution.'}, {'id': 'act11', 'topic': 'Science reasoning', 'difficulty': 'foundation', 'text': 'An experiment changes only the amount of sunlight and measures plant height. The independent variable is:', 'options': ['Plant height', 'Amount of sunlight', 'Plant type', 'Measurement ruler'], 'correct': 1, 'explanation': 'The independent variable is deliberately changed.'}, {'id': 'act12', 'topic': 'Science reasoning', 'difficulty': 'intermediate', 'text': 'Trial A has 12 successes in 20 attempts; Trial B has 15 in 30. Which has the higher success rate?', 'options': ['A', 'B', 'Same', 'Cannot compare'], 'correct': 0, 'explanation': 'A = 60%; B = 50%.'}], 'TOEFL': [{'id': 'toefl01', 'topic': 'Academic reading', 'difficulty': 'foundation', 'text': '“The hypothesis was supported by the observations.” Here “supported” most nearly means:', 'options': ['carried physically', 'backed by evidence', 'published', 'criticized'], 'correct': 1, 'explanation': 'The observations provided evidence for the hypothesis.'}, {'id': 'toefl02', 'topic': 'Academic reading', 'difficulty': 'foundation', 'text': 'A passage says a species migrates in winter to find food. What is the stated reason for migration?', 'options': ['Avoiding predators', 'Finding food', 'Changing color', 'Building nests'], 'correct': 1, 'explanation': 'The passage identifies food availability as the reason.'}, {'id': 'toefl03', 'topic': 'Academic reading', 'difficulty': 'intermediate', 'text': '“Although the lake was shallow, it supported diverse organisms.” What does although signal?', 'options': ['Cause', 'Contrast', 'Sequence', 'Definition'], 'correct': 1, 'explanation': 'Although introduces a contrast between shallowness and biodiversity.'}, {'id': 'toefl04', 'topic': 'Academic reading', 'difficulty': 'intermediate', 'text': 'A study found attendance rose after a tutoring program launched, but class schedules also changed. What remains uncertain?', 'options': ['The attendance figures', 'Whether tutoring alone caused the rise', 'Whether schedules changed', 'The study location'], 'correct': 1, 'explanation': 'Multiple simultaneous changes prevent a single causal conclusion.'}, {'id': 'toefl05', 'topic': 'Vocabulary', 'difficulty': 'foundation', 'text': 'Which word is closest in meaning to “significant” in “a significant increase”?', 'options': ['minor', 'important', 'secret', 'temporary'], 'correct': 1, 'explanation': 'Significant here means notable or important.'}, {'id': 'toefl06', 'topic': 'Vocabulary', 'difficulty': 'foundation', 'text': 'Choose the best word: “The researchers ____ data for three months.”', 'options': ['collected', 'collecting', 'collection', 'collects'], 'correct': 0, 'explanation': 'A completed past action needs past tense collected.'}, {'id': 'toefl07', 'topic': 'Vocabulary', 'difficulty': 'intermediate', 'text': '“The evidence is inconclusive.” This means the evidence:', 'options': ['is definitely false', 'does not support a firm conclusion', 'cannot be measured', 'was collected yesterday'], 'correct': 1, 'explanation': 'Inconclusive means insufficient to decide firmly.'}, {'id': 'toefl08', 'topic': 'Vocabulary', 'difficulty': 'intermediate', 'text': 'Choose the best academic transition: “The sample was small; ____, results should be interpreted cautiously.”', 'options': ['moreover', 'therefore', 'similarly', 'meanwhile'], 'correct': 1, 'explanation': 'Therefore signals a consequence.'}, {'id': 'toefl09', 'topic': 'Language use', 'difficulty': 'foundation', 'text': 'Choose the correct form: “The results ____ published yesterday.”', 'options': ['was', 'were', 'is', 'has'], 'correct': 1, 'explanation': 'Plural subject results takes were.'}, {'id': 'toefl10', 'topic': 'Language use', 'difficulty': 'foundation', 'text': 'Choose the best completion: “Students should take notes ____ listening to a lecture.”', 'options': ['during', 'while', 'unless', 'despite'], 'correct': 1, 'explanation': 'While introduces the action listening.'}, {'id': 'toefl11', 'topic': 'Language use', 'difficulty': 'intermediate', 'text': 'Choose the clearest sentence.', 'options': ['The findings suggest temperature may affect growth.', 'The findings temperature affect growth definitely.', 'Temperature, its growth, suggest finding.', 'The findings means temperature will always affect growth.'], 'correct': 0, 'explanation': 'The first is grammatical and avoids overclaiming.'}, {'id': 'toefl12', 'topic': 'Language use', 'difficulty': 'intermediate', 'text': 'The phrase “in contrast” is used to:', 'options': ['add a similar example', 'introduce an opposing point', 'describe a method', 'give a definition'], 'correct': 1, 'explanation': 'In contrast highlights a difference.'}], 'IELTS': [{'id': 'ielts01', 'topic': 'Academic reading', 'difficulty': 'foundation', 'text': 'A timetable states that the museum closes at 6 p.m. on weekdays. On Tuesday it closes at:', 'options': ['4 p.m.', '5 p.m.', '6 p.m.', '7 p.m.'], 'correct': 2, 'explanation': 'Tuesday is a weekday, so the closing time is 6 p.m.'}, {'id': 'ielts02', 'topic': 'Academic reading', 'difficulty': 'foundation', 'text': '“Many coastal towns depend on fishing.” Depend on most nearly means:', 'options': ['avoid', 'rely on', 'measure', 'oppose'], 'correct': 1, 'explanation': 'To depend on something means to rely on it.'}, {'id': 'ielts03', 'topic': 'Academic reading', 'difficulty': 'intermediate', 'text': 'A report finds that recycling increased while landfill waste decreased. Which statement is supported?', 'options': ['Recycling caused all of the decrease.', 'Two trends occurred together; their cause is not established.', 'Landfill waste rose.', 'The town eliminated waste.'], 'correct': 1, 'explanation': 'The two trends are stated without causal proof.'}, {'id': 'ielts04', 'topic': 'Academic reading', 'difficulty': 'intermediate', 'text': 'A notice says applications received after Friday will be considered only if places remain. Which is true?', 'options': ['Late applications are guaranteed.', 'All late applications are rejected.', 'Late applications may be considered if space remains.', 'Friday applications are invalid.'], 'correct': 2, 'explanation': 'The notice gives a condition for late consideration.'}, {'id': 'ielts05', 'topic': 'Vocabulary', 'difficulty': 'foundation', 'text': 'Choose a synonym for “approximately.”', 'options': ['exactly', 'roughly', 'rarely', 'suddenly'], 'correct': 1, 'explanation': 'Approximately means roughly or about.'}, {'id': 'ielts06', 'topic': 'Vocabulary', 'difficulty': 'foundation', 'text': 'Choose the correct word: “The graph shows a steady ____ in sales.”', 'options': ['increase', 'increasingly', 'increased', 'increases'], 'correct': 0, 'explanation': 'A noun is required after “a steady”.'}, {'id': 'ielts07', 'topic': 'Vocabulary', 'difficulty': 'intermediate', 'text': '“The decline was gradual.” Gradual means:', 'options': ['sudden', 'happening over time', 'unexpectedly large', 'reversed'], 'correct': 1, 'explanation': 'Gradual indicates a slow change over time.'}, {'id': 'ielts08', 'topic': 'Vocabulary', 'difficulty': 'intermediate', 'text': 'Which phrase is most appropriate for describing an upward trend in a report?', 'options': ['went bonkers', 'rose steadily', 'was super awesome', 'kind of did stuff'], 'correct': 1, 'explanation': 'Rose steadily is precise and suitably formal.'}, {'id': 'ielts09', 'topic': 'Grammar', 'difficulty': 'foundation', 'text': 'Choose the correct sentence.', 'options': ['There are less cars today.', 'There are fewer cars today.', 'There is fewer cars today.', 'There are little cars today.'], 'correct': 1, 'explanation': 'Use fewer with countable plural nouns.'}, {'id': 'ielts10', 'topic': 'Grammar', 'difficulty': 'foundation', 'text': 'Choose the best completion: “If it rains, the event ____ indoors.”', 'options': ['move', 'will move', 'moving', 'moved yesterday'], 'correct': 1, 'explanation': 'A first conditional commonly uses will + base verb.'}, {'id': 'ielts11', 'topic': 'Grammar', 'difficulty': 'intermediate', 'text': 'Which sentence is correctly punctuated?', 'options': ['However the results, were mixed.', 'However, the results were mixed.', 'However the results were, mixed.', 'However; the results were mixed.'], 'correct': 1, 'explanation': 'Use a comma after an introductory conjunctive adverb.'}, {'id': 'ielts12', 'topic': 'Grammar', 'difficulty': 'intermediate', 'text': 'Choose the most natural academic expression.', 'options': ['The experiment had a high number of data.', 'The experiment produced a large amount of data.', 'The experiment produce many datas.', 'The experiment producing much datas.'], 'correct': 1, 'explanation': 'Data is generally treated as a mass noun in this expression.'}], 'DET': [{'id': 'det01', 'topic': 'Read and select', 'difficulty': 'foundation', 'text': 'Which is a correctly spelled English word?', 'options': ['accomodate', 'accommodate', 'accomadate', 'acommodate'], 'correct': 1, 'explanation': 'Accommodate has double c and double m.'}, {'id': 'det02', 'topic': 'Read and select', 'difficulty': 'foundation', 'text': 'Which is a correctly spelled English word?', 'options': ['necessary', 'neccessary', 'necesary', 'nessesary'], 'correct': 0, 'explanation': 'Necessary has one c and double s.'}, {'id': 'det03', 'topic': 'Read and select', 'difficulty': 'intermediate', 'text': 'Which is a correctly spelled English word?', 'options': ['seperate', 'separate', 'seperete', 'separete'], 'correct': 1, 'explanation': 'Separate contains a after the r in the first syllable.'}, {'id': 'det04', 'topic': 'Read and select', 'difficulty': 'intermediate', 'text': 'Which is a correctly spelled English word?', 'options': ['definately', 'definitley', 'definitely', 'definetely'], 'correct': 2, 'explanation': 'Definitely is spelled d-e-f-i-n-i-t-e-l-y.'}, {'id': 'det05', 'topic': 'Fill in the blank', 'difficulty': 'foundation', 'text': 'Choose the best word: “She has ____ finished her homework.”', 'options': ['already', 'yetly', 'neverly', 'recent'], 'correct': 0, 'explanation': 'Already is a natural adverb with the present perfect.'}, {'id': 'det06', 'topic': 'Fill in the blank', 'difficulty': 'foundation', 'text': 'Choose the best completion: “They are interested ____ astronomy.”', 'options': ['at', 'on', 'in', 'for'], 'correct': 2, 'explanation': 'The standard preposition is interested in.'}, {'id': 'det07', 'topic': 'Fill in the blank', 'difficulty': 'intermediate', 'text': 'Choose the best word: “The findings were ____ with earlier research.”', 'options': ['consistent', 'consistence', 'consistently', 'consisting'], 'correct': 0, 'explanation': 'Consistent with means in agreement with.'}, {'id': 'det08', 'topic': 'Fill in the blank', 'difficulty': 'intermediate', 'text': 'Choose the best word: “The proposal was revised to ____ reviewers’ concerns.”', 'options': ['address', 'advice', 'avoidance', 'arrangement'], 'correct': 0, 'explanation': 'Address concerns means respond to or deal with them.'}, {'id': 'det09', 'topic': 'Reading', 'difficulty': 'foundation', 'text': '“A new path was built so visitors could reach the garden.” Why was the path built?', 'options': ['To reach the garden', 'To replace the garden', 'To close the garden', 'To study plants'], 'correct': 0, 'explanation': 'The stated purpose is to allow access to the garden.'}, {'id': 'det10', 'topic': 'Reading', 'difficulty': 'foundation', 'text': '“The library will open earlier during exams.” What will change?', 'options': ['The library location', 'The opening time', 'The number of books', 'The exam date'], 'correct': 1, 'explanation': 'The statement says the library will open earlier.'}, {'id': 'det11', 'topic': 'Reading', 'difficulty': 'intermediate', 'text': '“Despite delays in shipping, the exhibit opened on schedule.” Which statement is true?', 'options': ['The exhibit was canceled.', 'Shipping was on time.', 'The exhibit opened as planned.', 'The exhibit opened months early.'], 'correct': 2, 'explanation': 'Despite indicates the delay did not prevent the planned opening.'}, {'id': 'det12', 'topic': 'Reading', 'difficulty': 'intermediate', 'text': '“The study is preliminary; researchers plan a larger trial.” What does preliminary suggest?', 'options': ['The results are final.', 'The work is an early stage.', 'No research was done.', 'The trial was illegal.'], 'correct': 1, 'explanation': 'Preliminary means early and not yet definitive.'}]}
